def run_causal_discovery(X: np.ndarray) -> GeneralGraph:
    """
    Hybrid causal discovery integrating constraint-based skeleton
    discovery with CPT-based orientation refinement.

    Step 1 (global constraint satisfaction): recover the skeleton with
    stable-PC chi-squared conditional independence tests, then augment
    it with pairs exhibiting strong CPT-based (BDeu marginal-likelihood)
    dependence that the CI tests missed (skeleton false negatives).

    Step 2 (local structure learning / CPT consistency): decide edge
    orientations by probabilistic consistency of the locally estimated
    CPTs — the Bayesian-Dirichlet (BDeu) marginal likelihood of each
    node given candidate parents — via iterated local search restricted
    to the candidate skeleton (add / delete / reverse, acyclic).

    Step 3: report the Markov equivalence class (CPDAG) of the learned
    DAG via dag2cpdag.
    """
    from causallearn.utils.PCUtils import SkeletonDiscovery
    from causallearn.utils.cit import CIT
    from causallearn.score.LocalScoreFunctionClass import LocalScoreClass
    from causallearn.score.LocalScoreFunction import local_score_BDeu
    from causallearn.utils.DAG2CPDAG import dag2cpdag

    n_samples, N = X.shape
    rng = np.random.default_rng(0)

    # ---------- Step 1: constraint-based skeleton discovery ----------
    if N <= 25:
        alpha = 0.20
    elif N <= 45:
        alpha = 0.15
    else:
        alpha = 0.10
    cit = CIT(X, "chisq")
    cg = SkeletonDiscovery.skeleton_discovery(
        X, alpha, cit, stable=True,
        background_knowledge=None, verbose=False,
        show_progress=False, node_names=None,
    )
    gmat = cg.G.graph
    skel = np.zeros((N, N), dtype=bool)
    for i in range(N):
        for j in range(i + 1, N):
            if gmat[i, j] != 0 or gmat[j, i] != 0:
                skel[i, j] = skel[j, i] = True

    # BDeu local score = (negative) log marginal likelihood of node's CPT
    score_func = LocalScoreClass(
        data=X, local_score_fun=local_score_BDeu, parameters=None
    )
    _memo = {}

    def s(j, parents):
        key = (j, tuple(parents))
        v = _memo.get(key)
        if v is None:
            v = score_func.score(j, list(parents))
            _memo[key] = v
        return v

    # --- Skeleton augmentation via CPT-based dependence checks ---
    # Recover CI-test false negatives: pairs whose single-parent BDeu
    # marginal likelihood improves markedly indicate real dependence.
    # Capped per node + significance margin to avoid overfitting noise.
    base = np.array([s(j, ()) for j in range(N)])
    extra = np.zeros((N, N), dtype=bool)
    for j in range(N):
        deltas = []
        for i in range(N):
            if i == j or skel[i, j]:
                continue
            d = s(j, (i,)) - base[j]
            if d < -2.0:
                deltas.append((d, i))
        deltas.sort()
        for d, i in deltas[:4]:
            extra[i, j] = extra[j, i] = True
    skel = skel | extra

    cand = [(i, j) for i in range(N) for j in range(N)
            if i != j and skel[i, j]]

    # ---------- Step 2: CPT-based orientation refinement ----------
    def _has_path(adj, src, tgt):
        visited = set()
        stack = [src]
        while stack:
            node = stack.pop()
            if node == tgt:
                return True
            if node in visited:
                continue
            visited.add(node)
            for c in np.where(adj[node] == 1)[0]:
                if int(c) not in visited:
                    stack.append(int(c))
        return False

    def _parents(adj, j):
        return tuple(sorted(int(p) for p in np.where(adj[:, j] == 1)[0]))

    def climb(adj):
        """Greedy best-first hill climb restricted to the skeleton."""
        local_scores = np.array([s(j, _parents(adj, j)) for j in range(N)])
        while True:
            best_delta = 0.0
            best_op = None
            for (i, j) in cand:
                if adj[i, j] == 0 and adj[j, i] == 0:
                    if not _has_path(adj, j, i):
                        pj = tuple(sorted(_parents(adj, j) + (i,)))
                        delta = s(j, pj) - local_scores[j]
                        if delta < best_delta - 1e-6:
                            best_delta = delta
                            best_op = ("add", i, j)
                elif adj[i, j] == 1:
                    pj = tuple(p for p in _parents(adj, j) if p != i)
                    delta = s(j, pj) - local_scores[j]
                    if delta < best_delta - 1e-6:
                        best_delta = delta
                        best_op = ("delete", i, j)
                    adj[i, j] = 0
                    if not _has_path(adj, i, j):
                        new_sj = s(j, _parents(adj, j))
                        pi = tuple(sorted(_parents(adj, i) + (j,)))
                        new_si = s(i, pi)
                        delta = (new_sj - local_scores[j]) + (new_si - local_scores[i])
                        if delta < best_delta - 1e-6:
                            best_delta = delta
                            best_op = ("reverse", i, j)
                    adj[i, j] = 1
            if best_op is None:
                break
            op, i, j = best_op
            if op == "add":
                adj[i, j] = 1
            elif op == "delete":
                adj[i, j] = 0
            else:
                adj[i, j] = 0
                adj[j, i] = 1
            local_scores[j] = s(j, _parents(adj, j))
            if op == "reverse":
                local_scores[i] = s(i, _parents(adj, i))
        return adj, float(local_scores.sum())

    def perturb(adj, k):
        """Apply k random skeleton-consistent moves (escape local optima)."""
        adj = adj.copy()
        for _ in range(k):
            i, j = cand[int(rng.integers(len(cand)))]
            if adj[i, j] == 0 and adj[j, i] == 0:
                if not _has_path(adj, j, i):
                    adj[i, j] = 1
            elif adj[i, j] == 1:
                if rng.random() < 0.5:
                    adj[i, j] = 0
                else:
                    adj[i, j] = 0
                    if _has_path(adj, i, j):
                        adj[i, j] = 1
                    else:
                        adj[j, i] = 1
        return adj

    best_adj, best_score = climb(np.zeros((N, N), dtype=int))
    n_edges = max(4, int(best_adj.sum()))
    n_restarts = 40 if len(cand) > 0 else 0
    for _ in range(n_restarts):
        k = max(3, n_edges // 6)
        adj2, sc2 = climb(perturb(best_adj, k))
        if sc2 < best_score - 1e-6:
            best_adj, best_score = adj2, sc2
            n_edges = max(4, int(best_adj.sum()))

    # ---------- Step 3: CPDAG formation ----------
    nodes = [GraphNode(f"X{i + 1}") for i in range(N)]
    G = GeneralGraph(nodes)
    for i in range(N):
        for j in range(N):
            if best_adj[i, j] == 1:
                G.add_directed_edge(nodes[i], nodes[j])
    return dag2cpdag(G)
