# =====================================================================
def run_causal_discovery(X: np.ndarray) -> GeneralGraph:
    """
    Hybrid algorithm (the proposed idea):
      1) Constraint-based skeleton discovery via chi-squared CI tests
         (PC-stable, bounded conditioning size, power-rule test skipping).
      2) Edge-orientation refinement using the data's conditional
         probability distributions: BDeu marginal likelihoods of the
         local CPTs (Dirichlet-smoothed against noise overfitting)
         decide directions via greedy search restricted to the skeleton,
         with random-restart perturbations to escape local optima.
      3) Convert the resulting DAG to its CPDAG.
    """
    from itertools import combinations
    from causallearn.utils.cit import CIT
    from causallearn.score.LocalScoreFunctionClass import LocalScoreClass
    from causallearn.score.LocalScoreFunction import local_score_BDeu
    from causallearn.utils.DAG2CPDAG import dag2cpdag

    n_samples, N = X.shape
    alpha = 0.05
    max_k = 3          # bound conditioning-set size
    power_ratio = 4    # require n >= 4 * contingency cells for a CI test
    max_subsets = 300  # cap subsets examined per pair/side/depth

    cards = np.array([max(2, len(np.unique(X[:, i]))) for i in range(N)])
    cit = CIT(X, "chisq")

    # ---- Step 1: PC-stable skeleton with reliability criterion ----
    skel = np.ones((N, N), dtype=bool)
    np.fill_diagonal(skel, False)

    def enough_power(i, j, S):
        cells = int(cards[i]) * int(cards[j])
        for s in S:
            cells *= int(cards[s])
        return n_samples >= power_ratio * cells

    for depth in range(0, max_k + 1):
        snapshot = skel.copy()
        if snapshot.sum(axis=1).max() - 1 < depth:
            break
        removals = []
        for i in range(N):
            for j in range(i + 1, N):
                if not snapshot[i, j]:
                    continue
                removed = False
                for side, other in ((i, j), (j, i)):
                    neigh = [k for k in range(N)
                             if snapshot[side, k] and k != other]
                    if len(neigh) < depth:
                        continue
                    tried = 0
                    for S in combinations(neigh, depth):
                        tried += 1
                        if tried > max_subsets:
                            break
                        if not enough_power(i, j, S):
                            continue
                        if cit(i, j, list(S)) > alpha:
                            removals.append((i, j))
                            removed = True
                            break
                    if removed:
                        break
        for i, j in removals:
            skel[i, j] = skel[j, i] = False

    # ---- Step 2: CPT-based orientation via BDeu consistency checks ----
    score_func = LocalScoreClass(
        data=X, local_score_fun=local_score_BDeu, parameters=None
    )
    cache = {}

    def sc(j, pa):
        key = (int(j), tuple(sorted(int(p) for p in pa)))
        if key not in cache:
            cache[key] = score_func.score(key[0], list(key[1]))
        return cache[key]

    def _has_path(adj, src, tgt):
        visited = set()
        stack = [src]
        while stack:
            node = stack.pop()
            if node == tgt:
                return True
            if node in visited:
                continue
            visited.add(node)
            for c in np.where(adj[node] == 1)[0]:
                if int(c) not in visited:
                    stack.append(int(c))
        return False

    def climb(adj, ls):
        improved = True
        while improved:
            improved = False
            best_delta = 0.0
            best_op = None
            for i in range(N):
                for j in range(N):
                    if i == j or not skel[i, j]:
                        continue
                    if adj[i, j] == 0 and adj[j, i] == 0:
                        if not _has_path(adj, j, i):
                            pj = np.where(adj[:, j] == 1)[0].tolist()
                            delta = sc(j, pj + [i]) - ls[j]
                            if delta < best_delta - 1e-6:
                                best_delta = delta
                                best_op = ("add", i, j)
                    elif adj[i, j] == 1:
                        pj = np.where(adj[:, j] == 1)[0].tolist()
                        delta = sc(j, [p for p in pj if p != i]) - ls[j]
                        if delta < best_delta - 1e-6:
                            best_delta = delta
                            best_op = ("delete", i, j)
                        adj[i, j] = 0
                        if not _has_path(adj, i, j):
                            d = (
                                sc(j, np.where(adj[:, j] == 1)[0].tolist())
                                - ls[j]
                                + sc(i, np.where(adj[:, i] == 1)[0].tolist() + [j])
                                - ls[i]
                            )
                            if d < best_delta - 1e-6:
                                best_delta = d
                                best_op = ("reverse", i, j)
                        adj[i, j] = 1
            if best_op is not None:
                op_type, i, j = best_op
                if op_type == "add":
                    adj[i, j] = 1
                elif op_type == "delete":
                    adj[i, j] = 0
                elif op_type == "reverse":
                    adj[i, j] = 0
                    adj[j, i] = 1
                ls[j] = sc(j, np.where(adj[:, j] == 1)[0].tolist())
                if op_type == "reverse":
                    ls[i] = sc(i, np.where(adj[:, i] == 1)[0].tolist())
                improved = True
        return adj, ls

    rng = np.random.default_rng(0)
    adj = np.zeros((N, N), dtype=int)
    ls = np.array([sc(j, []) for j in range(N)], dtype=float)
    adj, ls = climb(adj, ls)
    best_adj, best_total = adj.copy(), ls.sum()

    skel_pairs = np.argwhere(skel)
    n_restarts = 40
    for _ in range(n_restarts):
        cur = best_adj.copy()
        # perturb: random deletes/reverses of current edges + random adds
        edges = np.argwhere(cur == 1)
        if len(edges) > 0:
            idx = rng.permutation(len(edges))[:3]
            for i, j in edges[idx]:
                cur[i, j] = 0
                if rng.random() < 0.5 and not _has_path(cur, i, j):
                    cur[j, i] = 1
        if len(skel_pairs) > 0:
            pidx = rng.permutation(len(skel_pairs))[:3]
            for i, j in skel_pairs[pidx]:
                if cur[i, j] == 0 and cur[j, i] == 0 and not _has_path(cur, j, i):
                    cur[i, j] = 1
        cur_ls = np.array(
            [sc(j, np.where(cur[:, j] == 1)[0].tolist()) for j in range(N)],
            dtype=float,
        )
        cur, cur_ls = climb(cur, cur_ls)
        if cur_ls.sum() < best_total - 1e-6:
            best_total = cur_ls.sum()
            best_adj = cur.copy()

    adj = best_adj

    # ---- Step 3: build DAG and convert to CPDAG ----
    nodes = [GraphNode(f"X{i + 1}") for i in range(N)]
    G = GeneralGraph(nodes)
    for i in range(N):
        for j in range(N):
            if adj[i, j] == 1:
                G.add_directed_edge(nodes[i], nodes[j])
    return dag2cpdag(G)
